<?php require '../common.php'; startpage('Borrow History and Fine');nav('<a href="index.php">Catalog</a><a href="admin.php">Admin</a>');$name=$_GET['student']??'';?>
<form><input name="student" placeholder="Student name" value="<?=e($name)?>" required><button>Search history</button></form>
<?php if($name):$s=$conn->prepare('SELECT l.*,b.title FROM loans l JOIN books b ON b.id=l.book_id WHERE l.student=?');$s->bind_param('s',$name);$s->execute();$rs=$s->get_result();?><table><tr><th>Book</th><th>Issue date</th><th>Due date</th><th>Status</th><th>Fine</th></tr><?php while($r=$rs->fetch_assoc()):$fine=$r['status']==='Returned'?$r['fine']:max(0,(int)((strtotime(date('Y-m-d'))-strtotime($r['due_date']))/86400))*10;?><tr><td><?=e($r['title'])?></td><td><?=$r['issue_date']?></td><td><?=$r['due_date']?></td><td><?=e($r['status'])?></td><td>₹<?=$fine?></td></tr><?php endwhile;?></table><?php endif;endpage();?>